+.slot {
+  position: relative;
+  min-width: 0;
+  --panel-left: 0;
+  --panel-right: auto;
+}
+
+.slot:has(.panel) {
+  z-index: 9;
+}
+
+.slot[data-expanded='true'] {
+  z-index: 10;
+}
+
+.preview {
+  height: 100%;
+}
+
+.expandButton,
+.panelHeader,
+.panelValue,
+.panelFooter {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 10px;
+}
+
+.expandButton {
+  width: 100%;
+  min-height: 36px;
+  margin-top: 8px;
+  padding: 4px 0;
+  border: 0;
+  background: transparent;
+  color: var(--dashboard-copy);
+  font-size: 0.68rem;
+  cursor: pointer;
+}
+
+.expandButton span {
+  display: inline-flex;
+  align-items: center;
+  gap: 3px;
